/** Basic, replaceable bots. Decisions accept only an information-limited view. */
import {auctionStatus,bidRank,isLegal,type Auction,type Call,type Seat,type Strain} from './auction';
import {controller,legalCards,rank,suit,winningPlay,type Game,type Played} from './play';
export const BOT_SYSTEM='BGM Natural 0.1';
export type BotView={seat:Seat;playSeat:Seat;hand:string[];playableHand:string[];dummy:{seat:Seat;cards:string[]}|null;auction:Auction;trick:Played[];played:Played[];trump:Strain|null};
export function botView(g:Game):BotView{const seat=controller(g),ds=g.contract?((g.contract.declarer+2)%4) as Seat:null;return {seat,playSeat:g.turn,hand:[...g.hands[seat]],playableHand:[...g.hands[g.turn]],dummy:g.dummyVisible&&ds!==null?{seat:ds,cards:[...g.hands[ds]]}:null,auction:structuredClone(g.auction),trick:g.trick.map(p=>({...p})),played:g.plays.map(p=>({...p})),trump:g.contract?.strain??null};}
export const hcp=(hand:string[])=>hand.reduce((n,c)=>n+({A:4,K:3,Q:2,J:1}[c[0]]??0),0);
const length=(hand:string[],st:string)=>hand.filter(c=>suit(c)===st).length;
const balanced=(hand:string[])=>{const shape=['C','D','H','S'].map(st=>length(hand,st)).sort((a,b)=>b-a).join('');return ['4333','4432','5332'].includes(shape);};
const naturalSuit=(hand:string[]):Strain=>{const h=length(hand,'H'),s=length(hand,'S');if(Math.max(h,s)>=5)return s>=h?'S':'H';const c=length(hand,'C'),d=length(hand,'D');return c===d?(c===3?'C':'D'):c>d?'C':'D';};
const pass:Call={kind:'pass'};
/** Explicit limited natural system. No convention claims or invisible partner HCP. */
export function chooseBid(v:BotView):Call{const a=v.auction,s=auctionStatus(a);if(s.finished||s.turn!==v.seat)throw Error('Not bot turn');const points=hcp(v.hand),own=a.history.filter(e=>e.seat===v.seat&&e.call.kind==='bid'),bids=a.history.filter(e=>e.call.kind==='bid');const partner=((v.seat+2)%4) as Seat,partnerBid=bids.filter(e=>e.seat===partner).at(-1),last=bids.at(-1);const bid=(level:number,strain:Strain):Call=>({kind:'bid',level,strain});let wanted:Call=pass;
 if(!bids.length){if(points>=22)wanted=bid(2,'C');else if(balanced(v.hand)&&points>=20&&points<=21)wanted=bid(2,'NT');else if(balanced(v.hand)&&points>=15&&points<=17)wanted=bid(1,'NT');else if(points>=12)wanted=bid(1,naturalSuit(v.hand));}
 else if(last&&last.seat%2!==v.seat%2){if(!own.length&&points>=10&&points<=17){const st=naturalSuit(v.hand);if(length(v.hand,st)>=5){const level=s.lastBid?.level??1;for(let n=level;n<=2;n++)if(isLegal(a,bid(n,st))&&(n===1||points>=12)){wanted=bid(n,st);break;}}}}
 else if(partnerBid?.call.kind==='bid'&&own.length===0){const p=partnerBid.call;if(p.strain==='NT'){const total=(p.level===1?15:20)+points;wanted=total>=25?bid(3,'NT'):p.level===1&&points>=8?bid(2,'NT'):pass;}
 else if(p.level===2&&p.strain==='C'){wanted=bid(2,'D');}
 else if(p.level===1&&length(v.hand,p.strain)>=(['H','S'].includes(p.strain)?3:4)&&points>=6){const target=['H','S'].includes(p.strain)?4:5;wanted=bid(points>=13?target:points>=10?3:2,p.strain);}
 else if(p.level===1&&points>=6){const majors=(['S','H'] as Strain[]).filter(st=>length(v.hand,st)>=4&&isLegal(a,bid(1,st)));if(majors.length)wanted=bid(1,majors.sort((x,y)=>length(v.hand,y)-length(v.hand,x))[0]);else if(points>=10){const st=naturalSuit(v.hand);wanted=length(v.hand,st)>=4&&isLegal(a,bid(2,st))?bid(2,st):bid(points>=13?3:2,'NT');}else wanted=bid(1,'NT');}}
 else if(own.length===1&&partnerBid?.call.kind==='bid'){const p=partnerBid.call;const first=own[0].call;if(first.kind==='bid'){if(first.level===2&&first.strain==='C'){const st=naturalSuit(v.hand);wanted=balanced(v.hand)?bid(2,'NT'):bid(2,st);}
 else if(p.strain==='NT'&&p.level===2&&points>=16)wanted=bid(3,'NT');
 else if(p.strain===first.strain&&p.level===3&&points>=15)wanted=bid(['H','S'].includes(p.strain)?4:5,p.strain);
 else if(p.strain!==first.strain&&['H','S'].includes(p.strain)&&length(v.hand,p.strain)>=4)wanted=bid(points>=16?4:2,p.strain);
 }}
 // Never chase partner endlessly. No slam, penalty-double or convention heuristics.
 if(own.length>=2)wanted=pass;
 if(wanted.kind==='bid'&&s.lastBid&&bidRank(wanted)<=bidRank(s.lastBid))wanted=pass;
 return isLegal(a,wanted)?wanted:pass;
}
export function chooseCard(v:BotView):string{const legal=legalCards(v.playableHand,v.trick).sort((a,b)=>rank(a)-rank(b)||suit(a).localeCompare(suit(b)));if(!legal.length)throw Error('No legal card');const trump=v.trump??'NT';if(v.trick.length){const winning=winningPlay(v.trick,trump);if(winning.seat%2===v.playSeat%2)return legal[0];const win=legal.filter(card=>winningPlay([...v.trick,{seat:v.playSeat,card}],trump).seat===v.playSeat);if(win.length)return win.sort((a,b)=>(suit(a)===trump?100:0)+rank(a)-(suit(b)===trump?100:0)-rank(b))[0];return legal[0];}
 const suits=['S','H','D','C'].filter(st=>length(legal,st)>0).sort((a,b)=>(length(legal,b)-(b===trump?2:0))-(length(legal,a)-(a===trump?2:0)));
 const cards=legal.filter(c=>suit(c)===suits[0]).sort((a,b)=>rank(b)-rank(a));
 if(cards.length>=2&&rank(cards[0])-rank(cards[1])===1&&rank(cards[0])>=8)return cards[0];
 const knownPlayed=new Set(v.played.map(p=>p.card));const topRemaining='AKQJT98765432'.split('').map(r=>r+suits[0]).find(c=>!knownPlayed.has(c));if(topRemaining&&cards.includes(topRemaining))return topRemaining;
 if(trump==='NT'&&cards.length>=4)return cards[3];return cards.at(-1)!;
}

