import {addCall,auctionStatus,dummySeat,nextSeat,type Auction,type Call,type Contract,type Seat} from './auction';
export type Played={seat:Seat;card:string};
export type Trick={cards:Played[];winner:Seat};
export type Game={schema:1;board:number;seed:number;initial:string[][];hands:string[][];auction:Auction;contract:Contract|null;phase:'auction'|'play'|'trick'|'done'|'passed';turn:Seat;trick:Played[];tricks:Trick[];plays:Played[];totals:[number,number];dummyVisible:boolean};
export const rank=(card:string)=>'23456789TJQKA'.indexOf(card[0]);
export const suit=(card:string)=>card.slice(-1);
export function boardInfo(board:number){if(!Number.isInteger(board)||board<1)throw Error('Invalid board');const pattern=['None','NS','EW','Both','NS','EW','Both','None','EW','Both','None','NS','Both','None','NS','EW'];return {dealer:((board-1)%4) as Seat,vulnerability:pattern[(board-1)%16]};}
export function vulnerable(board:number,seat:Seat){const v=boardInfo(board).vulnerability;return v==='Both'||v===(seat%2===0?'NS':'EW');}
export function dealSeed(seed:number){let value=seed>>>0;const deck=['C','D','H','S'].flatMap(st=>'23456789TJQKA'.split('').map(r=>r+st));for(let i=51;i>0;i--){value=(Math.imul(value,1664525)+1013904223)>>>0;const j=value%(i+1);[deck[i],deck[j]]=[deck[j],deck[i]];}return [0,1,2,3].map(seat=>deck.filter((_,i)=>i%4===seat));}
export function newGame(board=1,seed=crypto.getRandomValues(new Uint32Array(1))[0]):Game{const hands=dealSeed(seed),dealer=boardInfo(board).dealer;return {schema:1,board,seed,initial:hands.map(h=>[...h]),hands,auction:{dealer,history:[]},contract:null,phase:'auction',turn:dealer,trick:[],tricks:[],plays:[],totals:[0,0],dummyVisible:false};}
export function bidGame(g:Game,call:Call):Game{if(g.phase!=='auction')throw Error('Auction closed');const auction=addCall(g.auction,call),s=auctionStatus(auction);return {...g,auction,contract:s.contract,phase:s.finished?(s.contract?'play':'passed'):'auction',turn:s.contract?.leader??s.turn};}
export function legalCards(hand:string[],trick:Played[]){if(trick.length===4)return [];if(!trick.length)return [...hand];const follow=hand.filter(c=>suit(c)===suit(trick[0].card));return follow.length?follow:[...hand];}
export function winningPlay(cards:Played[],trump:string):Played{if(!cards.length)throw Error('Empty trick');return cards.reduce((win,p)=>{const ws=suit(win.card),ps=suit(p.card);if(ps===ws)return rank(p.card)>rank(win.card)?p:win;if(ps===trump&&ws!==trump)return p;return win;});}
export function controller(g:Game):Seat{if(!g.contract)return g.turn;return g.turn===dummySeat(g.contract)?g.contract.declarer:g.turn;}
export function playCard(g:Game,seat:Seat,card:string):Game{if(g.phase!=='play'||seat!==g.turn||!legalCards(g.hands[seat],g.trick).includes(card))throw Error('Illegal card or turn');const played={seat,card},trick=[...g.trick,played],hands=g.hands.map((h,i)=>i===seat?h.filter(c=>c!==card):h);return {...g,hands,trick,plays:[...g.plays,played],turn:nextSeat(seat),phase:trick.length===4?'trick':'play',dummyVisible:true};}
export function collectTrick(g:Game):Game{if(g.phase!=='trick'||!g.contract)throw Error('Trick incomplete');const winner=winningPlay(g.trick,g.contract.strain).seat,totals:[number,number]=[...g.totals];totals[winner%2]++;const tricks=[...g.tricks,{cards:g.trick,winner}];return {...g,tricks,totals,trick:[],turn:winner,phase:tricks.length===13?'done':'play'};}
/** Duplicate scoring, declarer's perspective. Law 77. */
export function scoreContract(c:Contract,tricks:number,vul:boolean){if(!Number.isInteger(tricks)||tricks<0||tricks>13)throw Error('Invalid trick count');const delta=tricks-(c.level+6);if(delta<0){const down=-delta;if(c.multiplier===1)return -down*(vul?100:50);const doubled=vul?200+(down-1)*300:down===1?100:down===2?300:500+(down-3)*300;return -doubled*(c.multiplier===4?2:1);}const minor=c.strain==='C'||c.strain==='D',unit=minor?20:30;const bidPoints=(c.level*unit+(c.strain==='NT'?10:0))*c.multiplier;const bonus=bidPoints>=100?(vul?500:300):50;const slam=c.level===6?(vul?750:500):c.level===7?(vul?1500:1000):0;const insult=c.multiplier===2?50:c.multiplier===4?100:0;const over=c.multiplier===1?delta*unit:delta*(vul?200:100)*(c.multiplier===4?2:1);return bidPoints+bonus+slam+insult+over;}
export function result(g:Game){if(g.phase==='passed')return {declarerTricks:0,delta:0,declarerScore:0,nsScore:0};if(g.phase!=='done'||!g.contract)return null;const declarerTricks=g.totals[g.contract.declarer%2],declarerScore=scoreContract(g.contract,declarerTricks,vulnerable(g.board,g.contract.declarer));return {declarerTricks,delta:declarerTricks-g.contract.level-6,declarerScore,nsScore:declarerScore*(g.contract.declarer%2===0?1:-1)};}
/** Persist an action log. Restore always replays validated rules, never trusts saved totals/hands. */
export type SavedGame={schema:1;board:number;seed:number;calls:Call[];plays:Played[];collected:number};
export function saveGame(g:Game):SavedGame{return {schema:1,board:g.board,seed:g.seed,calls:g.auction.history.map(e=>e.call),plays:g.plays,collected:g.tricks.length};}
export function restoreGame(value:unknown):Game{const v=value as SavedGame;if(!v||v.schema!==1||!Number.isInteger(v.seed)||v.seed<0||v.seed>0xffffffff||!Array.isArray(v.calls)||v.calls.length>320||!Array.isArray(v.plays)||v.plays.length>52||!Number.isInteger(v.collected)||v.collected<0||v.collected>13)throw Error('Invalid saved game');let g=newGame(v.board,v.seed);for(const call of v.calls)g=bidGame(g,call);for(const p of v.plays){if(g.phase==='trick')g=collectTrick(g);g=playCard(g,p.seat,p.card);}if(g.phase==='trick'&&v.collected===g.tricks.length+1)g=collectTrick(g);if(g.tricks.length!==v.collected)throw Error('Invalid collected tricks');return g;}

