/** Independent auction rules. No bots, UI, storage or hidden-card analysis. */
export type Seat=0|1|2|3;
export const STRAINS=['C','D','H','S','NT'] as const;
export type Strain=typeof STRAINS[number];
export type Bid={kind:'bid';level:number;strain:Strain};
export type Call=Bid|{kind:'pass'}|{kind:'double'}|{kind:'redouble'};
export type Entry={seat:Seat;call:Call};
export type Auction={dealer:Seat;history:Entry[]};
export type Contract={level:number;strain:Strain;declarer:Seat;leader:Seat;multiplier:1|2|4};
export const nextSeat=(seat:Seat)=>(seat+1)%4 as Seat;
export const bidRank=(bid:Bid)=>(bid.level-1)*5+STRAINS.indexOf(bid.strain);
export function auctionStatus(a:Auction){
 let lastBid:Bid|null=null,bidder:Seat|null=null,passes=0,multiplier:1|2|4=1;
 for(const {seat,call} of a.history){if(call.kind==='bid'){lastBid=call;bidder=seat;passes=0;multiplier=1;}else if(call.kind==='pass'){passes++;}else{passes=0;multiplier=call.kind==='double'?2:4;}}
 const finished=lastBid?passes>=3:passes>=4;
 const turn=(a.dealer+a.history.length)%4 as Seat;
 let contract:Contract|null=null;
 if(finished&&lastBid&&bidder!==null){
  const first=a.history.find(e=>e.seat%2===bidder!%2&&e.call.kind==='bid'&&e.call.strain===lastBid!.strain)!;
  contract={level:lastBid.level,strain:lastBid.strain,declarer:first.seat,leader:nextSeat(first.seat),multiplier};
 }
 return {lastBid,bidder,multiplier,passes,finished,turn,contract};
}
export function isLegal(a:Auction,call:Call){
 const s=auctionStatus(a);if(s.finished)return false;
 if(call.kind==='pass')return true;
 if(call.kind==='bid')return Number.isInteger(call.level)&&call.level>=1&&call.level<=7&&STRAINS.includes(call.strain)&&(!s.lastBid||bidRank(call)>bidRank(s.lastBid));
 if(!s.lastBid||s.bidder===null)return false;
 if(call.kind==='double')return s.multiplier===1&&s.turn%2!==s.bidder%2;
 if(call.kind==='redouble')return s.multiplier===2&&s.turn%2===s.bidder%2;
 return false;
}
export function addCall(a:Auction,call:Call):Auction{
 if(!isLegal(a,call))throw Error('Illegal call');
 return {...a,history:[...a.history,{seat:auctionStatus(a).turn,call}]};
}
/** A complete deterministic training deal. Each card appears once. */
export function trainingDeal():string[][]{
 const deck=STRAINS.slice(0,4).flatMap(s=>'AKQJT98765432'.split('').map(r=>r+s));
 let seed=63841;
 for(let i=deck.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[deck[i],deck[j]]=[deck[j],deck[i]];}
 return [0,1,2,3].map(seat=>deck.filter((_,i)=>i%4===seat).sort((a,b)=>'SHDC'.indexOf(a.slice(-1))-'SHDC'.indexOf(b.slice(-1))||'AKQJT98765432'.indexOf(a[0])-'AKQJT98765432'.indexOf(b[0])));
}
/** Display preference: trump left, alternating suit colours, ace down to two. */
export function suitOrder(trump:Strain|null=null):string[]{
 const base=['C','D','S','H'];if(!trump||trump==='NT')return base;
 const start=base.indexOf(trump);return [...base.slice(start),...base.slice(0,start)];
}
export function sortHand(cards:string[],trump:Strain|null=null):string[]{
 const order=suitOrder(trump),ranks='AKQJT98765432';
 return [...cards].sort((a,b)=>order.indexOf(a.slice(-1))-order.indexOf(b.slice(-1))||ranks.indexOf(a[0])-ranks.indexOf(b[0]));
}
export function dummySeat(contract:Contract):Seat{return (contract.declarer+2)%4 as Seat;}
export function canSeeHand(seat:Seat,player:Seat,contract:Contract|null,openingLeadShown:boolean):boolean{
 return seat===player||Boolean(openingLeadShown&&contract&&seat===dummySeat(contract));
}
/** Demonstration only: a legal card from the opening leader's hand, no AI. */
export function sampleOpeningLead(hands:string[][],contract:Contract):{seat:Seat;card:string}{
 const card=sortHand(hands[contract.leader],contract.strain).at(-1);
 if(!card)throw Error('Opening leader has no cards');
 return {seat:contract.leader,card};
}

