const sym:Record<string,string>={C:'♣',D:'♦',H:'♥',S:'♠',NT:'NT'},CURRENT='bgm-solo-current-v1',HISTORY='bgm-solo-history-v1';
function initial(){try{const raw=localStorage.getItem(CURRENT);if(raw)return restoreGame(JSON.parse(raw));}catch{}return newGame();}
function pastGames(){try{const raw=JSON.parse(localStorage.getItem(HISTORY)??'[]');if(!Array.isArray(raw))return [];return raw.slice(-20).map(restoreGame).filter(g=>g.phase==='done'||g.phase==='passed');}catch{return [];}}
export default function SolitaireTable({lang,onBack,initialGame,rubberMode}:{lang:Language;onBack:()=>void;initialGame?:Game;rubberMode?:{scorecard:ReactNode;names:string[];vulnerability:string;onNext:(g:Game)=>void;finished:boolean;closed:boolean;locked:boolean}}){
 const c=text[lang],[g,setGame]=useState<Game>(()=>initialGame??initial()),[past,setPast]=useState<Game[]>(()=>rubberMode?[]:pastGames()),[tab,setTab]=useState<'auction'|'scores'|'review'>('auction'),[review,setReview]=useState(0),[call,setCall]=useState<Call>({kind:'pass'}),[level,setLevel]=useState(1),[expanded,setExpanded]=useState(false),[error,setError]=useState('');const help=useRef<HTMLDialogElement>(null),analysisDialog=useRef<HTMLDialogElement>(null),human:Seat=2;
 const status=auctionStatus(g.auction),contract=g.contract,ds=contract?((contract.declarer+2)%4) as Seat:null,actor=controller(g),humanTurn=g.phase==='auction'?g.turn===human:g.phase==='play'&&actor===human;
 const board={...boardInfo(g.board),dealer:g.auction.dealer,...(rubberMode?{vulnerability:rubberMode.vulnerability}:{})},ended=g.phase==='done'||g.phase==='passed',cardLegal=humanTurn&&g.phase==='play'?legalCards(g.hands[g.turn],g.trick):[],score=result(g),rgame=past[review]??past.at(-1);
 const strainName=(st:Strain)=>st==='NT'?c.nt:sym[st];
 function describe(a:Call){return a.kind==='bid'?a.level+strainName(a.strain):a.kind==='pass'?c.pass:a.kind==='double'?'X':'XX';}
 function change(fn:(old:Game)=>Game){try{setGame(fn(g));}catch{setError(c.invalid);}}
 useEffect(()=>{if(rubberMode)return;try{localStorage.setItem(CURRENT,JSON.stringify(saveGame(g)));}catch{setError(c.saveError);}},[g,c.saveError]);
 useEffect(()=>{if(!ended)return;setPast(old=>{const id=g.board+':'+g.seed;if(old.some(p=>p.board+':'+p.seed===id))return old;const next=[...old,g].slice(-20);try{if(!rubberMode)localStorage.setItem(HISTORY,JSON.stringify(next.map(saveGame)));}catch{setError(c.saveError);}return next;});setTab('scores');},[ended,g.board,g.seed]);
 useEffect(()=>{if((g.phase==='auction'&&g.turn!==human)||(g.phase==='play'&&actor!==human)){const timer=setTimeout(()=>{try{const v=botView(g);setGame(g.phase==='auction'?bidGame(g,chooseBid(v)):playCard(g,g.turn,chooseCard(v)));}catch{setError(c.invalid);}},350);return()=>clearTimeout(timer);}},[g,actor,c.invalid]);
 useEffect(()=>{if(g.phase!=='trick')return;const timer=setTimeout(()=>setGame(collectTrick(g)),1500);return()=>clearTimeout(timer);},[g]);
 useEffect(()=>{const sync=()=>setExpanded(Boolean(document.fullscreenElement));document.addEventListener('fullscreenchange',sync);return()=>document.removeEventListener('fullscreenchange',sync);},[]);
 async function expand(){if(expanded){setExpanded(false);if(document.fullscreenElement)await document.exitFullscreen().catch(()=>{});}else{setExpanded(true);await document.documentElement.requestFullscreen?.().catch(()=>{});}}
 function next(){if(rubberMode){if(ended)rubberMode.onNext(g);return;}if(!ended&&!window.confirm(c.newAsk))return;setGame(newGame(g.board+1));setCall({kind:'pass'});setLevel(1);setError('');setTab('auction');}
 function faces(seat:Seat,side=false){const cards=sortHand(g.hands[seat],contract?.strain??null);const card=(value:string)=>{const can=cardLegal.includes(value)&&g.turn===seat;return <button type="button" key={value} className={'solo-card card-suit-'+suit(value)} disabled={!can} aria-label={value.replace('T','10')} onClick={()=>change(old=>playCard(old,seat,value))}><b>{value[0]==='T'?'10':value[0]}</b><span>{sym[suit(value)]}</span></button>;};if(side){const suits=[...new Set(cards.map(suit))];return <div className="solo-side-suits">{suits.flatMap(st=>{const group=cards.filter(v=>suit(v)===st);return Array.from({length:Math.ceil(group.length/6)},(_,i)=><div className="solo-side-suit" key={st+i}>{group.slice(i*6,i*6+6).map(card)}</div>);})}</div>;}return <div className="solo-hand" role="group" aria-label={c.seats[seat]} style={{gridTemplateColumns:`repeat(${Math.max(0,cards.length-1)},minmax(0,1fr)) var(--solo-card-w)`,maxWidth:`calc(${Math.max(0,cards.length-1)} * 28px + var(--solo-card-w))`}}>{cards.map(card)}</div>;}
 function hand(seat:Seat){const dummy=g.dummyVisible&&seat===ds;const visible=seat===human||dummy;return <section key={seat} className={'solo-seat solo-seat-'+seat+(dummy?' solo-dummy':'')+((g.phase==='auction'||g.phase==='play')&&g.turn===seat?' solo-active':'')} aria-label={c.seats[seat]}><div className="solo-seat-name"><strong>{c.seats[seat]}{seat===human?' · '+c.you:''}</strong><span>{dummy?c.dummy:seat===human?g.hands[seat].length+' '+c.remaining:(rubberMode?rubberMode.names[seat]:c.bot)+' · '+g.hands[seat].length}</span></div>{visible?faces(seat,seat===1||seat===3):<div className="solo-backs" aria-label={g.hands[seat].length+' '+c.remaining}>{g.hands[seat].map((_,i)=><span key={i} className="solo-back" aria-hidden="true">♠</span>)}</div>}</section>;}
 const analysisGame=tab==='review'&&rgame?rgame:ended?g:null;
 const analysisText=analysisGame?analysisCopy[lang][3]+'\n\n'+JSON.stringify({notation:'Seats 0 North, 1 East, 2 South, 3 West. Suits S spades H hearts D diamonds C clubs NT no-trump. T ten. Play order preserved.',board:analysisGame.board,boardInfo:boardInfo(analysisGame.board),hands:analysisGame.initial,auction:analysisGame.auction,contract:analysisGame.contract,plays:analysisGame.plays,tricks:analysisGame.tricks,result:result(analysisGame),system:BOT_SYSTEM},null,2):'';
 useEffect(()=>{if(ended&&rubberMode&&!rubberMode.finished)rubberMode.onNext(g);},[ended,g]);
 const trickWinner=g.phase==='trick'&&contract?winningPlay(g.trick,contract.strain).seat:null;
 return <main className={'solo-screen'+(expanded?' solo-expanded':'')+(g.dummyVisible&&ds===1?' solo-dummy-east':g.dummyVisible&&ds===3?' solo-dummy-west':'')}><div className="solo-toolbar"><button onClick={onBack} aria-label={c.club}>←</button><strong>BGM BRIDGE <small>0.18</small></strong><span>{rubberMode?'Rubber · bots básicos':c.title}</span><div><button disabled={Boolean(rubberMode)&&!ended} onClick={next} title={c.next} aria-label={c.next}>↻</button><button onClick={expand} title={expanded?c.compact:c.expand} aria-label={expanded?c.compact:c.expand}>⛶</button><button onClick={()=>help.current?.showModal()} aria-label={c.agreements} title={c.agreements}>?</button></div></div>
 <div className="solo-meta"><span>{c.board} {g.board}</span><span>{c.dealer}: {c.short[board.dealer]}</span><span>{c.vul}: {c.vuls[board.vulnerability as keyof typeof c.vuls]}</span><strong>{contract?<SuitText text={`${contract.level}${strainName(contract.strain)}${contract.multiplier===2?' X':contract.multiplier===4?' XX':''} · ${c.declarer}: ${c.short[contract.declarer]}`}/>:c.auction}</strong></div>
 <div className="solo-layout"><section className="solo-board" aria-label={c.title}>{tab==='review'&&rgame&&<div className="solo-review-table" aria-label={c.review}>{([0,1,2,3] as Seat[]).map(seat=><div className={"solo-review-hand review-seat-"+seat} key={seat}><strong>{c.seats[seat]}</strong>{['S','H','D','C'].map(st=><span key={st} className={'review-suit suit-'+st}>{sym[st]} {sortHand(rgame.initial[seat]).filter(v=>suit(v)===st).map(v=>v[0]==='T'?'10':v[0]).join(' ')||'—'}</span>)}</div>)}<div className="review-center"><strong>BGM BRIDGE</strong><span>{c.board} {rgame.board}</span><span>{rgame.contract?rgame.contract.level+strainName(rgame.contract.strain)+' · '+c.seats[rgame.contract.declarer]:c.passed}</span></div></div>}{([0,1,2,3] as Seat[]).map(hand)}<div className="solo-middle"><div className="solo-table-cards" aria-label={c.trick}>{g.trick.map(p=><div key={p.seat} className={'played-seat played-'+p.seat}><small>{c.short[p.seat]}</small><span className={'solo-card played-card card-suit-'+suit(p.card)} aria-label={p.card.replace('T','10')}><b>{p.card[0]==='T'?'10':p.card[0]}</b><span>{sym[suit(p.card)]}</span></span></div>)}</div>{!g.trick.length&&<div className="solo-watermark">BGM<span>BRIDGE</span></div>}<div className="solo-center-status" aria-live="polite">{ended?c.finished:g.phase==='trick'?c.won+': '+c.seats[trickWinner!]:g.phase==='auction'?c.turn+': '+c.seats[g.turn]:c.trick+' '+(g.tricks.length+1)+' · '+c.turn+': '+c.seats[g.turn]}</div></div></section>
 <aside className="solo-panel"><div className="solo-tabs">{(['auction','scores','review'] as const).map(k=><button key={k} className={tab===k?'on':''} onClick={()=>setTab(k)}>{c[k]}</button>)}</div><div className="solo-panel-content">{analysisGame&&<button className="analysis-open" onClick={()=>analysisDialog.current?.showModal()}>✦ {analysisCopy[lang][0]}</button>}{rubberMode&&<p>Rubber: la planilla está en «Resultados».</p>}{tab==='auction'?<><table className="solo-auction-history"><thead><tr>{c.short.map(st=><th key={st}>{st}</th>)}</tr></thead><tbody>{Array.from({length:Math.max(1,Math.ceil((g.auction.dealer+g.auction.history.length)/4))},(_,row)=><tr key={row}>{[0,1,2,3].map(col=>{const i=row*4+col-g.auction.dealer;const entry=g.auction.history[i];return <td key={col} className={entry?.call.kind==='bid'&&'HD'.includes(entry.call.strain)?'red-call':''}>{entry&&i>=0?<SuitText text={describe(entry.call)}/>: '—'}</td>;})}</tr>)}</tbody></table><p className="solo-system">{BOT_SYSTEM}</p></>:tab==='scores'?rubberMode?rubberMode.scorecard:<>{!past.length?<p>{c.noScores}</p>:<table className="solo-scores"><thead><tr><th>{c.board}</th><th>{c.contract}</th><th>{sides[lang][0]}<small>{c.ns}</small></th><th>{sides[lang][1]}<small>{c.ew}</small></th></tr></thead><tbody>{past.map((p,i)=><tr key={p.seed+':'+p.board}><td><button onClick={()=>{setReview(i);setTab('review');}}>{p.board}</button></td><td>{p.contract?p.contract.level+strainName(p.contract.strain)+(p.contract.multiplier===2?' X':p.contract.multiplier===4?' XX':'')+' '+c.short[p.contract.declarer]:'—'}<small>{p.contract?' ('+(result(p)!.delta===0?'=':result(p)!.delta>0?'+'+result(p)!.delta:result(p)!.delta)+')':''}</small></td><td>{Math.max(0,result(p)?.nsScore??0)}</td><td>{Math.max(0,-(result(p)?.nsScore??0))}</td></tr>)}</tbody><tfoot><tr><th colSpan={2}>{lang==='it'?'Totale':lang==='zh'?'总计':'Total'}</th><td>{past.reduce((sum,p)=>sum+Math.max(0,result(p)?.nsScore??0),0)}</td><td>{past.reduce((sum,p)=>sum+Math.max(0,-(result(p)?.nsScore??0)),0)}</td></tr></tfoot></table>}</>:<><small>{c.previous}</small>{rgame?<><select aria-label={c.show} value={past.indexOf(rgame)} onChange={e=>setReview(Number(e.target.value))}>{past.map((p,i)=><option key={p.seed+':'+p.board} value={i}>{c.board} {p.board}</option>)}</select><p>{c.review} · {c.board} {rgame.board}</p></>:<p>{c.noReview}</p>}</>}</div><div className="solo-totals"><span>{c.trick}: {g.tricks.length}/13</span><strong>{c.ns} {g.totals[0]} · {c.ew} {g.totals[1]}</strong></div></aside></div>
 <section className={'solo-controls'+(g.phase==='auction'?' is-auction':'')} aria-label={g.phase==='auction'?'Bidding box':c.choose}>{g.phase==='auction'?<><div className="solo-levels" aria-label={c.level}>{[1,2,3,4,5,6,7].map(n=><button key={n} disabled={!humanTurn||!STRAINS.some(st=>isLegal(g.auction,{kind:'bid',level:n,strain:st}))} className={call.kind==='bid'&&level===n?'on':''} onClick={()=>{setLevel(n);const strain=call.kind==='bid'&&isLegal(g.auction,{kind:'bid',level:n,strain:call.strain})?call.strain:STRAINS.find(st=>isLegal(g.auction,{kind:'bid',level:n,strain:st}))!;setCall({kind:'bid',level:n,strain});}}>{n}</button>)}</div><div className="solo-strains" aria-label={c.strain}>{STRAINS.map(st=><button key={st} disabled={!humanTurn||!isLegal(g.auction,{kind:'bid',level,strain:st})} className={(call.kind==='bid'&&call.strain===st?'on ':'')+('HD'.includes(st)?'red-call':'')} onClick={()=>setCall({kind:'bid',level,strain:st})}>{<SuitText text={strainName(st)}/>}</button>)}</div><div className="solo-special">{([['pass',c.pass],['double','X'],['redouble','XX']] as const).map(([kind,label])=><button key={kind} disabled={!humanTurn||!isLegal(g.auction,{kind})} className={call.kind===kind?'on':''} onClick={()=>setCall({kind})}>{label}</button>)}</div><button className="solo-confirm gold" disabled={!humanTurn||!isLegal(g.auction,call)} onClick={()=>change(old=>bidGame(old,call))}>{c.confirm}<strong><SuitText text={describe(call)}/></strong></button></>:g.phase==='trick'?<><strong>{c.trick} {g.tricks.length+1} · {c.won}: {c.seats[trickWinner!]}</strong></>:ended?<><strong>{rubberMode?(rubberMode.finished?(rubberMode.closed?'Serie de cuatro manos terminada · Ver Resultados':'Mano anotada'):'Mano terminada · Anotar resultado'):g.phase==='passed'?c.passed:`${c.result}: ${score!.delta===0?'=':score!.delta>0?'+'+score!.delta:score!.delta} · ${c.points}: ${score!.nsScore}`}</strong><button className="gold" disabled={rubberMode?.locked} onClick={next}>{rubberMode?(rubberMode.finished?(rubberMode.closed?'Nueva serie · Rotar bots':c.next):'Anotar mano'):c.next}</button></>:<><div aria-live="polite"><strong>{humanTurn?c.choose:g.dummyVisible&&ds===human?c.dummyNotice:c.wait}</strong><small>{humanTurn?c.follow:c.thinking}</small></div></>}</section><dialog className="solo-help analysis-dialog" ref={analysisDialog}><button onClick={()=>analysisDialog.current?.close()}>{c.close}</button><h2>{analysisCopy[lang][0]}</h2><p>{analysisCopy[lang][1]}</p><label>{analysisCopy[lang][2]}<textarea readOnly value={analysisText} onFocus={e=>e.currentTarget.select()} rows={14}/></label></dialog>{error&&<p className="solo-error" role="alert">{error}</p>}
 <dialog ref={help} className="solo-help"><button className="close" aria-label={c.close} onClick={()=>help.current?.close()}>✕</button><h2>{c.agreements}</h2><p>{c.help}</p><h3>{BOT_SYSTEM}</h3><p>{c.agreementsText}</p><small>{c.resume}</small></dialog></main>;
