test('registro, seguridad de sesión y persistencia al reiniciar',async()=>{
 const dir=mkdtempSync(join(tmpdir(),'bgm-test-')),port=15188,base=`http://localhost:${port}`;let child;
 async function start(){child=spawn(process.execPath,['server/server.mjs'],{env:{...process.env,BGM_DATA_DIR:dir,BGM_PORT:String(port)},stdio:['ignore','pipe','pipe']});await new Promise((ok,no)=>{child.stdout.once('data',ok);child.once('exit',()=>no(Error('Servidor no arrancó')));});}
 async function stop(){const done=once(child,'exit');child.kill('SIGTERM');await done;}
 async function post(path,data,cookie='',origin=base){return fetch(base+'/api/'+path,{method:'POST',headers:{'Content-Type':'application/json',Origin:origin,Cookie:cookie},body:JSON.stringify(data)});}
 const account={name:'Alejandro',email:'PRUEBA@example.com',password:'Prueba-local-1234',confirm:'Prueba-local-1234'};
 try{await start();
 assert.equal((await post('register',{...account,confirm:'distinta'})).status,400);
 assert.equal((await post('register',account,'','https://otro.example')).status,403);
 const registered=await post('register',account);assert.equal(registered.status,200);const header=registered.headers.get('set-cookie');assert.match(header,/HttpOnly/);assert.match(header,/SameSite=Strict/);const cookie=header.split(';')[0];
 assert.equal((await registered.json()).user.name,'Alejandro');
 assert.equal((await post('register',{...account,email:'prueba@example.com'})).status,400);
 assert.equal((await post('login',{email:account.email,password:'equivocada'})).status,401);
 assert.equal((await (await fetch(base+'/api/me',{headers:{Cookie:cookie}})).json()).user.name,'Alejandro');
 await stop();await start();
 assert.equal((await (await fetch(base+'/api/me',{headers:{Cookie:cookie}})).json()).user.email,'prueba@example.com');
 const db=new DatabaseSync(join(dir,'bridge.sqlite'));const stored=db.prepare('SELECT * FROM members').get();assert.notEqual(stored.hash,account.password);assert.equal(stored.hash.length,128);db.close();
 assert.equal((await post('logout',{},cookie)).status,200);assert.equal((await (await fetch(base+'/api/me',{headers:{Cookie:cookie}})).json()).user,null);
 const signed=await post('login',account);assert.equal(signed.status,200);
 for(let i=0;i<21;i++)await post('login',{email:account.email,password:'incorrecta'});
 assert.equal((await post('login',account)).status,429);
 }finally{if(child?.exitCode===null)await stop();rmSync(dir,{recursive:true,force:true});}
});

