import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import ts from 'typescript';
const code=ts.transpileModule(readFileSync(new URL('../src/auction.ts',import.meta.url),'utf8'),{compilerOptions:{module:ts.ModuleKind.ESNext,target:ts.ScriptTarget.ES2022}}).outputText;
const {addCall,auctionStatus,isLegal,trainingDeal}=await import('data:text/javascript;base64,'+Buffer.from(code).toString('base64'));
const pass={kind:'pass'},double={kind:'double'},redouble={kind:'redouble'},bid=(level,strain)=>({kind:'bid',level,strain});
const run=(calls,dealer=0)=>calls.reduce(addCall,{dealer,history:[]});
test('reparto: 52 cartas únicas, 13 por puesto',()=>{const hands=trainingDeal();assert.deepEqual(hands.map(h=>h.length),[13,13,13,13]);assert.equal(new Set(hands.flat()).size,52);});
test('cuatro pasos: sin contrato y no admite más voces',()=>{const a=run([pass,pass,pass,pass]);assert.equal(auctionStatus(a).finished,true);assert.equal(auctionStatus(a).contract,null);assert.equal(isLegal(a,bid(1,'C')),false);assert.throws(()=>addCall(a,pass));});
test('orden de palos, niveles y sin triunfo',()=>{const a=run([bid(1,'S')]);assert.equal(isLegal(a,bid(1,'H')),false);assert.equal(isLegal(a,bid(1,'S')),false);assert.equal(isLegal(a,bid(1,'NT')),true);assert.equal(isLegal(a,bid(2,'C')),true);assert.equal(isLegal(a,bid(8,'C')),false);assert.equal(isLegal(a,bid(0,'NT')),false);});
test('1ST 3ST: contrato y primer declarante del bando',()=>{const a=run([bid(1,'NT'),pass,bid(3,'NT'),pass,pass,pass]);assert.deepEqual(auctionStatus(a).contract,{level:3,strain:'NT',declarer:0,leader:1,multiplier:1});});
test('doblo solo adversario; redoblo solo bando declarante',()=>{assert.equal(isLegal(run([]),double),false);assert.equal(isLegal(run([bid(1,'C'),pass]),double),false);assert.equal(isLegal(run([bid(1,'C')]),double),true);assert.equal(isLegal(run([bid(1,'C'),double]),double),false);assert.equal(isLegal(run([bid(1,'C'),double]),redouble),true);assert.equal(isLegal(run([bid(1,'C'),double,pass]),redouble),false);});
test('doblo tras pasos, redoblo y tres pasos',()=>{const a=run([bid(1,'H'),pass,pass,double,redouble,pass,pass,pass]);assert.deepEqual(auctionStatus(a).contract,{level:1,strain:'H',declarer:0,leader:1,multiplier:4});});
test('nueva oferta borra doblo y reinicia los pasos',()=>{const a=run([bid(1,'C'),double,bid(1,'H'),pass,pass]);assert.equal(auctionStatus(a).multiplier,1);assert.equal(auctionStatus(a).finished,false);assert.equal(auctionStatus(addCall(a,pass)).contract.multiplier,1);});
test('bando contrario gana: no confundir primer jugador del palo',()=>{const a=run([bid(1,'H'),bid(1,'S'),bid(2,'H'),bid(2,'S'),pass,pass,pass]);assert.deepEqual(auctionStatus(a).contract,{level:2,strain:'S',declarer:1,leader:2,multiplier:1});});
test('inmutabilidad y turno tras deshacer',()=>{const a=run([bid(1,'C')]);const b=addCall(a,pass);assert.equal(a.history.length,1);assert.equal(b.history.length,2);assert.equal(auctionStatus({...b,history:b.history.slice(0,-1)}).turn,1);});
test('dador distinto y contrato 7ST',()=>{const a=run([bid(7,'NT'),pass,pass,pass],3);assert.deepEqual(auctionStatus(a).contract,{level:7,strain:'NT',declarer:3,leader:0,multiplier:1});});
const {sortHand,suitOrder,dummySeat,canSeeHand}=await import('data:text/javascript;base64,'+Buffer.from(code).toString('base64'));
test('orden acordado: triunfo izquierda y colores alternados',()=>{assert.deepEqual(suitOrder('NT'),['C','D','S','H']);assert.deepEqual(suitOrder('C'),['C','D','S','H']);assert.deepEqual(suitOrder('D'),['D','S','H','C']);assert.deepEqual(suitOrder('H'),['H','C','D','S']);assert.deepEqual(suitOrder('S'),['S','H','C','D']);assert.deepEqual(sortHand(['2H','AS','TH','AH','KC','3D'],'H'),['AH','TH','2H','KC','3D','AS']);});
test('durante subasta solo Sur ve sus cartas, aunque sea turno de otro',()=>{for(let seat=0;seat<4;seat++)assert.equal(canSeeHand(seat,2,null,false),seat===2);});
test('el muerto no se descubre al terminar la subasta: espera salida',()=>{const contract=auctionStatus(run([bid(1,'NT'),pass,bid(3,'NT'),pass,pass,pass])).contract;assert.equal(dummySeat(contract),2);assert.equal(canSeeHand(0,2,contract,false),false);assert.equal(canSeeHand(1,2,contract,false),false);});
test('con Sur declarante, solo Norte se descubre tras salida',()=>{const contract=auctionStatus(run([pass,pass,bid(1,'S'),pass,pass,pass])).contract;assert.equal(dummySeat(contract),0);for(let seat=0;seat<4;seat++){assert.equal(canSeeHand(seat,2,contract,false),seat===2);assert.equal(canSeeHand(seat,2,contract,true),seat===2||seat===0);}});
test('con Sur defensor, muerto es el compañero del declarante, no el suyo',()=>{const contract=auctionStatus(run([pass,bid(1,'NT'),pass,pass,pass])).contract;assert.equal(dummySeat(contract),3);assert.equal(canSeeHand(0,2,contract,true),false);assert.equal(canSeeHand(1,2,contract,true),false);assert.equal(canSeeHand(2,2,contract,true),true);assert.equal(canSeeHand(3,2,contract,true),true);});
const {sampleOpeningLead}=await import('data:text/javascript;base64,'+Buffer.from(code).toString('base64'));
test('salida de prueba: mano correcta, 52 cartas conservadas, solo una retirada',()=>{const hands=trainingDeal();for(const declarer of [0,1,2,3]){const contract={level:1,strain:'NT',declarer,leader:(declarer+1)%4,multiplier:1};const lead=sampleOpeningLead(hands,contract);assert.equal(lead.seat,(declarer+1)%4);assert.ok(hands[lead.seat].includes(lead.card));const after=hands.map((h,i)=>i===lead.seat?h.filter(c=>c!==lead.card):h);assert.equal(after[lead.seat].length,12);assert.equal(after.flat().length+1,52);assert.equal(new Set([...after.flat(),lead.card]).size,52);assert.equal(canSeeHand(dummySeat(contract),declarer,contract,false),false);assert.equal(canSeeHand(dummySeat(contract),declarer,contract,true),true);}});

