import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import ts from 'typescript';
const cache=new Map();function moduleURL(name){if(cache.has(name))return cache.get(name);let source=ts.transpileModule(readFileSync(new URL('../src/'+name+'.ts',import.meta.url),'utf8'),{compilerOptions:{module:ts.ModuleKind.ESNext,target:ts.ScriptTarget.ES2022}}).outputText;source=source.replace(/from ['"]\.\/(\w+)['"]/g,(_,dep)=>'from '+JSON.stringify(moduleURL(dep)));const url='data:text/javascript;base64,'+Buffer.from(source).toString('base64');cache.set(name,url);return url;}
const {newGame,bidGame,legalCards,playCard,collectTrick,winningPlay,scoreContract,boardInfo,vulnerable,result,saveGame,restoreGame,controller}=await import(moduleURL('play'));
const {botView,chooseBid,chooseCard,hcp}=await import(moduleURL('bots'));
const {isLegal}=await import(moduleURL('auction'));
const pass={kind:'pass'},bid=(level,strain)=>({kind:'bid',level,strain});
function contracted(declarer=0,strain='NT',seed=41){let g=newGame(1,seed);for(let i=0;i<declarer;i++)g=bidGame(g,pass);for(const c of [bid(3,strain),pass,pass,pass])g=bidGame(g,c);return g;}
function finish(g,check=true){let n=0;while(g.phase==='auction'){assert.ok(n++<100);const v=botView(g);const call=chooseBid(v);assert.ok(isLegal(g.auction,call));g=bidGame(g,call);}while(!['done','passed'].includes(g.phase)){assert.ok(n++<200);if(g.phase==='trick'){g=collectTrick(g);continue;}const v=botView(g),card=chooseCard(v);assert.ok(legalCards(g.hands[g.turn],g.trick).includes(card));g=playCard(g,g.turn,card);if(check){assert.equal(new Set([...g.hands.flat(),...g.plays.map(p=>p.card)]).size,52);assert.equal(g.hands.flat().length+g.plays.length,52);}}return g;}
test('obligación de asistir y rechazo de cartas fuera de turno o ajenas',()=>{assert.deepEqual(legalCards(['2H','AS'],[{seat:0,card:'KH'}]),['2H']);assert.deepEqual(legalCards(['AS','2C'],[{seat:0,card:'KH'}]),['AS','2C']);let g=contracted();assert.throws(()=>playCard(g,0,g.hands[0][0]));assert.throws(()=>playCard(g,g.turn,'XX'));const own=g.hands[g.turn][0];const next=playCard(g,g.turn,own);assert.ok(g.hands[g.turn].includes(own));assert.equal(next.plays.length,1);});
test('ganador por rango, palo de salida y triunfo; no gana un descarte alto',()=>{const cards=[{seat:0,card:'2H'},{seat:1,card:'AS'},{seat:2,card:'KH'},{seat:3,card:'AC'}];assert.equal(winningPlay(cards,'NT').seat,2);assert.equal(winningPlay(cards,'S').seat,1);assert.equal(winningPlay([{seat:0,card:'AH'},{seat:1,card:'2S'},{seat:2,card:'KS'},{seat:3,card:'QS'}],'S').seat,2);});
test('muerto solo después de salida y control por declarante en cuatro puestos',()=>{for(let d=0;d<4;d++){let g=contracted(d);const ds=(d+2)%4;assert.equal(g.dummyVisible,false);assert.equal(botView(g).dummy,null);g=playCard(g,g.turn,g.hands[g.turn][0]);assert.equal(g.dummyVisible,true);assert.equal(botView(g).dummy.seat,ds);while(g.phase==='play'&&g.turn!==ds)g=playCard(g,g.turn,legalCards(g.hands[g.turn],g.trick)[0]);if(g.phase==='play')assert.equal(controller(g),d);}});
test('tabla de puntuación duplicada: parciales, mangas, slams, doblo y redoblo',()=>{const c=(level,strain,multiplier=1)=>({level,strain,multiplier,declarer:2,leader:3});for(const [contract,tricks,vul,expected] of [[c(1,'NT'),7,false,90],[c(3,'NT'),9,false,400],[c(3,'NT'),10,true,630],[c(4,'H'),10,false,420],[c(5,'D'),11,true,600],[c(2,'S',2),8,false,470],[c(2,'H',4),9,true,1240],[c(6,'NT'),12,false,990],[c(6,'H'),12,true,1430],[c(7,'C'),13,false,1440],[c(7,'S'),13,true,2210],[c(3,'NT'),8,false,-50],[c(4,'S'),8,true,-200],[c(4,'S',2),9,false,-100],[c(4,'S',2),8,false,-300],[c(4,'S',2),7,false,-500],[c(4,'S',2),6,false,-800],[c(4,'S',2),8,true,-500],[c(4,'S',4),7,true,-1600]])assert.equal(scoreContract(contract,tricks,vul),expected,JSON.stringify(contract)+' '+tricks);});
test('rotación de dador y ciclo de vulnerabilidad de 16 manos',()=>{assert.equal(boardInfo(1).dealer,0);assert.equal(boardInfo(4).dealer,3);assert.equal(boardInfo(17).vulnerability,'None');assert.equal(vulnerable(2,0),true);assert.equal(vulnerable(2,1),false);assert.equal(vulnerable(3,3),true);assert.equal(vulnerable(4,2),true);});
test('100 manos completas y puntuadas: 4 declarantes y 5 denominaciones',()=>{for(let i=0;i<100;i++){const d=i%4,st=['C','D','H','S','NT'][i%5];const g=finish(contracted(d,st,i+100));assert.equal(g.phase,'done');assert.equal(g.plays.length,52);assert.equal(g.tricks.length,13);assert.equal(g.totals[0]+g.totals[1],13);assert.equal(g.hands.flat().length,0);assert.equal(result(g).nsScore,result(g).declarerScore*(d%2===0?1:-1));}});
test('250 subastas y manos completas de bots, sin bucles ni jugadas ilegales',()=>{for(let seed=1;seed<=250;seed++){const g=finish(newGame((seed%16)+1,seed*7919),false);assert.ok(['done','passed'].includes(g.phase));if(g.phase==='done')assert.equal(g.tricks.length,13);}});
test('aislamiento: intercambiar cartas ocultas no cambia la vista ni decisión del bot',()=>{let g=contracted(2,'S');g=playCard(g,g.turn,g.hands[g.turn][0]);const v=botView(g);const visible=[v.seat,v.playSeat,v.dummy.seat];const hidden=[0,1,2,3].filter(s=>!visible.includes(s));assert.equal(hidden.length,2);const altered=structuredClone(g);[altered.hands[hidden[0]],altered.hands[hidden[1]]]=[altered.hands[hidden[1]],altered.hands[hidden[0]]];assert.deepEqual(botView(altered),v);assert.equal(chooseCard(botView(altered)),chooseCard(v));assert.equal('hands' in v,false);assert.equal('initial' in v,false);assert.equal('seed' in v,false);});
test('subasta: la decisión de apertura solo depende de mano propia y voces públicas',()=>{const g=newGame(1,127);const altered=structuredClone(g);[altered.hands[1],altered.hands[3]]=[altered.hands[3],altered.hands[1]];assert.deepEqual(botView(g),botView(altered));assert.deepEqual(chooseBid(botView(g)),chooseBid(botView(altered)));});
test('recuperación exacta tras voz, carta, baza completa, recogida y fin',()=>{let g=contracted(2,'H');assert.deepEqual(restoreGame(saveGame(g)),g);for(let i=0;i<52;i++){g=playCard(g,g.turn,chooseCard(botView(g)));assert.deepEqual(restoreGame(saveGame(g)),g);if(g.phase==='trick'){g=collectTrick(g);assert.deepEqual(restoreGame(saveGame(g)),g);}}assert.equal(g.phase,'done');const broken=saveGame(g);broken.plays[1]={...broken.plays[1],card:broken.plays[0].card};assert.throws(()=>restoreGame(broken));});
test('4 pasos terminan sin contrato y recuperan cero puntos',()=>{let g=newGame(1,9);for(let i=0;i<4;i++)g=bidGame(g,pass);assert.equal(g.phase,'passed');assert.equal(result(g).nsScore,0);assert.deepEqual(restoreGame(saveGame(g)),g);});

