import type {Game} from './play';
export type Rubber={above:[number,number];below:[number,number];games:[number,number];partial:[number,number];done:boolean;hands:number};
export const emptyRubber=():Rubber=>({above:[0,0],below:[0,0],games:[0,0],partial:[0,0],done:false,hands:0});
export function rubberHand(old:Rubber,g:Game,classic=true,vulnerableOverride?:boolean,gameBonus=false):Rubber{if(old.done||!['done','passed'].includes(g.phase))throw Error('Rubber cerrado o mano sin terminar');const r:Rubber={...old,above:[...old.above],below:[...old.below],games:[...old.games],partial:[...old.partial],hands:old.hands+1};if(!g.contract)return r;const c=g.contract,t=(c.declarer%2) as 0|1,other=(1-t) as 0|1,v=vulnerableOverride??(old.games[t]>0),d=g.totals[t]-6-c.level,m=c.multiplier,unit=c.strain==='C'||c.strain==='D'?20:30;
// Honores: una sola mano, independientemente del bando declarante.
for(let seat=0;seat<4;seat++){const h=g.initial[seat],n=c.strain==='NT'?h.filter(x=>x[0]==='A').length:h.filter(x=>x.endsWith(c.strain)&&'AKQJT'.includes(x[0])).length;const bonus=c.strain==='NT'?(n===4?150:0):n===5?150:n===4?100:0;r.above[seat%2 as 0|1]+=bonus;}
if(d<0){const down=-d;r.above[other]+=m===1?down*(v?100:50):(v?200+(down-1)*300:down===1?100:down===2?300:500+(down-3)*300)*(m===4?2:1);return r;}
const below=(unit*c.level+(c.strain==='NT'?10:0))*m;r.below[t]+=below;r.partial[t]+=below;r.above[t]+=d*(m===1?unit:(v?200:100)*(m===4?2:1))+(m===2?50:m===4?100:0)+(c.level===6?(v?750:500):c.level===7?(v?1500:1000):0);
if(r.partial[t]>=100){if(gameBonus)r.above[t]+=v?500:300;r.games[t]++;r.partial=[0,0];if(classic&&r.games[t]===2){r.done=true;r.above[t]+=r.games[other]?500:700;}}return r;}
export function settlement(r:Rubber,rate=100){if(!r.done)throw Error('Rubber sin terminar');const diff=r.above[0]+r.below[0]-r.above[1]-r.below[1],c=Math.sign(diff)*Math.floor((Math.abs(diff)+50)/100)*rate;return {difference:diff,movements:[c,-c,c,-c]};}

export function seriesHand(old:Rubber,g:Game):Rubber{if(old.hands>=4)throw Error('Serie cerrada');const v=seriesVulnerability(old.hands);const side=g.contract?g.contract.declarer%2:0;const r=rubberHand(old,g,false,v==='Both'||v===(side===0?'NS':'EW'),true);return {...r,done:r.hands===4};}

export function seriesVulnerability(index:number){return (['None','EW','NS','Both'] as const)[Math.min(3,Math.max(0,index))];}

