import SuitText from './SuitText';
import {newGame,type Game} from './play';
import {emptyRubber,seriesHand,seriesVulnerability,settlement,type Rubber} from './rubber';
import {individualTotals,rotateSeats,finalBalances,type PendingSeries} from './rubberLedger';
import type {Language} from './i18n';
type ScoreRow={board:number;contract:string;before:Rubber;after:Rubber;rubber:number};
const labels=['Bot 1','Bot 2','Tú','Bot 3'],winds=['Norte','Este','Sur','Oeste'];
function freshGame(board=1,first=0):Game{const g=newGame(board),deck=['S','H','D','C'].flatMap(s=>'23456789TJQKA'.split('').map(r=>r+s));for(let i=51;i>0;i--){const n=i+1,limit=4294967296-4294967296%n;let x;do{x=crypto.getRandomValues(new Uint32Array(1))[0]}while(x>=limit);const j=x%n;[deck[i],deck[j]]=[deck[j],deck[i]];}const hands=Array.from({length:4},(_,i)=>deck.slice(i*13,i*13+13)),dealer=((first+board-1)%4) as 0|1|2|3;return {...g,initial:hands.map(h=>[...h]),hands,auction:{dealer,history:[]},turn:dealer};}
export default function RubberTable({lang,onBack}:{lang:Language;onBack:()=>void}){
 const [draw]=useState(()=>crypto.getRandomValues(new Uint32Array(1))[0]%4),[rubber,setRubber]=useState(emptyRubber),[game,setGame]=useState(()=>freshGame(1,draw)),[finished,setFinished]=useState<Game|null>(null),[credits,setCredits]=useState([19600,19600,19600,19600]),[rate,setRate]=useState(100),[seats,setSeats]=useState([0,1,2,3]),[rows,setRows]=useState<ScoreRow[]>([]),[seriesNumber,setSeriesNumber]=useState(1),[summaries,setSummaries]=useState<PendingSeries[]>([]),[approvals,setApprovals]=useState([false,false,false,false]),[settled,setSettled]=useState(false),[error,setError]=useState('');const applied=useRef(false);
 const complete=summaries.length===3,totals=individualTotals(summaries),v=seriesVulnerability(rubber.hands-(finished?1:0));
 function advance(g:Game){if(!finished){const r=seriesHand(rubber,g),c=g.contract;setRows(a=>[...a,{board:g.board,rubber:seriesNumber,before:rubber,after:r,contract:c?c.level+({C:'♣',D:'♦',H:'♥',S:'♠',NT:'ST'}[c.strain])+(c.multiplier===2?' X':c.multiplier===4?' XX':'')+' '+['N','E','S','O'][c.declarer]+' · '+(g.totals[c.declarer%2]-6-c.level):'Todos pasan'}]);setRubber(r);setFinished(g);if(r.done){const x=settlement(r,rate);setSummaries(a=>[...a,{number:seriesNumber,difference:x.difference,movements:x.movements,seats:[...seats]}]);}return;}
 if(rubber.done){if(complete&&!settled)return;if(complete){setSummaries([]);setRows([]);setApprovals([false,false,false,false]);setSettled(false);applied.current=false;setSeriesNumber(1);}else setSeriesNumber(n=>n+1);setSeats(rotateSeats(seats));setRubber(emptyRubber());}setFinished(null);setGame(freshGame(game.board+1,draw));}
 function approve(id:number){if(!complete||settled)return;setApprovals(a=>a.map((v,i)=>i===id?true:v));}
 function liquidate(){if(applied.current)return;try{const next=finalBalances(credits,summaries,approvals);applied.current=true;setCredits(next);setSettled(true);setError('');}catch(e){setError((e as Error).message);}}
 const compass=<div className="rubber-compass" role="group" aria-label="Orden sorteado y vulnerabilidad"><div className={'compass-cross'+(v==='Both'||v==='NS'?' vulnerable-ns':'')+(v==='Both'||v==='EW'?' vulnerable-ew':'')} aria-hidden="true"/>{seats.map((id,seat)=><div key={seat} className={'compass-seat compass-seat-'+seat+((v==='Both'||v===(seat%2===0?'NS':'EW'))?' is-vulnerable':'')}><b>{((seat-draw+4)%4)+1}</b><strong>{winds[seat]}</strong><span>{labels[id]}</span>{(v==='Both'||v===(seat%2===0?'NS':'EW'))&&<small>Vulnerable</small>}</div>)}</div>;
