/tr>)}</tbody></table><button className="gold" disabled={settled||!approvals.every(Boolean)} onClick={liquidate}>{settled?'Liquidación completada':'Liquidar créditos ficticios'}</button>{error&&<p role="alert">{error}</p>}</>}</section><RubberScorecard rubber={rubber} rows={rows} number={seriesNumber} vulnerability={v}/></>;
