function RubberScorecard({rubber,rows,number,vulnerability}:{vulnerability:string;rubber:Rubber;rows:{board:number;contract:string;before:Rubber;after:Rubber;rubber:number}[];number:number}){return <div className="rubber-scorecard"><h3>Planilla · Serie {number}</h3><div className="rubber-vulnerability"><span className={vulnerability==='Both'||vulnerability==='NS'?'vulnerable':'nonvulnerable'}>Nosotros · N/S · {vulnerability==='Both'||vulnerability==='NS'?'Vulnerables':'No vulnerables'}</span><span className={vulnerability==='Both'||vulnerability==='EW'?'vulnerable':'nonvulnerable'}>Ellos · E/O · {vulnerability==='Both'||vulnerability==='EW'?'Vulnerables':'No vulnerables'}</span></div><table><thead><tr><th>Actual</th><th>Nosotros<br/>N/S</th><th>Ellos<br/>E/O</th></tr></thead><tbody><tr><th>Sobre la línea</th>{rubber.above.map((n,i)=><td key={i}>{n}</td>)}</tr><tr className="below-line"><th>Parcial hacia 100</th>{rubber.partial.map((n,i)=><td key={i}><strong>{n} / 100</strong></td>)}</tr><tr><th>Mangas ganadas</th>{rubber.games.map((n,i)=><td key={i}>{n}</td>)}</tr><tr><th>Bajo la línea acumulado</th>{rubber.below.map((n,i)=><td key={i}>{n}</td>)}</tr><tr className="rubber-score-total"><th>Total</th><td>{rubber.above[0]+rubber.below[0]}</td><td>{rubber.above[1]+rubber.below[1]}</td></tr></tbody></table>{!rows.length?<p>Las manos se anotan automáticamente al terminar.</p>:<><h4>Manos anotadas · de la primera a la última</h4>{rows.map((r,i)=>{const manga=r.after.games[0]>r.before.games[0]?0:r.after.games[1]>r.before.games[1]?1:null;return <section className="rubber-score-entry" key={i}><strong>Serie {r.rubber} · Mano {r.board} · {<SuitText text={r.contract}/>}</strong><small>Vulnerabilidad al jugar: N/S {seriesVulnerability(r.before.hands)==='Both'||seriesVulnerability(r.before.hands)==='NS'?'sí':'no'} · E/O {seriesVulnerability(r.before.hands)==='Both'||seriesVulnerability(r.before.hands)==='EW'?'sí':'no'}</small><table><thead><tr><th>Puntos de esta mano</th><th>N/S</th><th>E/O</th></tr></thead><tbody><tr><th>Sobre</th><td>{r.after.above[0]-r.before.above[0]}</td><td>{r.after.above[1]-r.before.above[1]}</td></tr><tr className="below-line"><th>Bajo</th><td>{r.after.below[0]-r.before.below[0]}</td><td>{r.after.below[1]-r.before.below[1]}</td></tr></tbody></table>{manga!==null&&<p className="manga-mark">MANGA {manga===0?'N/S':'E/O'} · Se cierran los parciales de ambos bandos</p>}{r.after.done&&<p className="manga-mark">FIN DE LA SERIE · Resultado pendiente de aprobación final</p>}</section>})}</>}</div>}

