import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import ts from 'typescript';
const cache=new Map();function moduleURL(name){if(cache.has(name))return cache.get(name);let source=ts.transpileModule(readFileSync(new URL('../src/'+name+'.ts',import.meta.url),'utf8'),{compilerOptions:{module:ts.ModuleKind.ESNext,target:ts.ScriptTarget.ES2022}}).outputText;source=source.replace(/from ['"]\.\/(\w+)['"]/g,(_,dep)=>'from '+JSON.stringify(moduleURL(dep)));const url='data:text/javascript;base64,'+Buffer.from(source).toString('base64');cache.set(name,url);return url;}

const {emptyRubber,rubberHand,seriesHand,seriesVulnerability,settlement}=await import(moduleURL('rubber'));
const {newGame}=await import(moduleURL('play'));
function hand(level,strain,tricks,decl=0,multiplier=1){return {...newGame(),initial:[[],[],[],[]],phase:'done',contract:{level,strain,declarer:decl,multiplier},totals:decl%2===0?[tricks,13-tricks]:[13-tricks,tricks]};}
test('parciales, manga, vulnerabilidad y rubber 2-0',()=>{let r=emptyRubber();r=rubberHand(r,hand(2,'H',8));assert.deepEqual(r.partial,[60,0]);r=rubberHand(r,hand(2,'H',8));assert.deepEqual(r.games,[1,0]);assert.deepEqual(r.partial,[0,0]);r=rubberHand(r,hand(3,'NT',9));assert.equal(r.done,true);assert.deepEqual(r.below,[220,0]);assert.deepEqual(r.above,[700,0]);const x=settlement(r);assert.equal(x.difference,920);assert.deepEqual(x.movements,[900,-900,900,-900]);assert.equal(x.movements.reduce((a,b)=>a+b),0);assert.throws(()=>rubberHand(r,hand(1,'C',7)));});
test('2-1, caidas vulnerables y parciales adversarios borrados',()=>{let r=emptyRubber();r=rubberHand(r,hand(3,'NT',9));r=rubberHand(r,hand(1,'NT',7,1));r=rubberHand(r,hand(4,'H',9));assert.equal(r.above[1],100);r=rubberHand(r,hand(4,'S',10,1));assert.deepEqual(r.games,[1,1]);assert.deepEqual(r.partial,[0,0]);r=rubberHand(r,hand(4,'H',10));assert.equal(r.above[0],500);assert.equal(r.done,true);});
test('doblados, slams y honores',()=>{let r=rubberHand(emptyRubber(),hand(2,'H',9,0,2));assert.deepEqual(r.below,[120,0]);assert.deepEqual(r.above,[150,0]);r=rubberHand(emptyRubber(),hand(6,'NT',12));assert.equal(r.above[0],500);const g=hand(1,'S',7);g.initial[1]=['AS','KS','QS','JS'];r=rubberHand(emptyRubber(),g);assert.equal(r.above[1],100);});

test('serie BGM termina en cuarta mano aunque no haya mangas',()=>{let r=emptyRubber();for(let i=0;i<4;i++){r=seriesHand(r,{...newGame(),phase:'passed'});assert.equal(r.done,i===3);}assert.deepEqual(settlement(r).movements,[0,-0,0,-0]);assert.throws(()=>seriesHand(r,hand(1,'S',7)));});
test('serie BGM permite cuatro mangas y no añade premio 700/500',()=>{let r=emptyRubber();for(let i=0;i<4;i++){r=seriesHand(r,hand(3,'NT',9));assert.equal(r.done,i===3);}assert.deepEqual(r.games,[4,0]);assert.deepEqual(r.below,[400,0]);assert.deepEqual(r.above,[1600,0]);assert.equal(settlement(r).difference,2000);});

const {individualTotals,rotateSeats,finalBalances}=await import(moduleURL('rubberLedger'));
test('todos contra todos: cada jugador comparte pareja con los otros tres',()=>{let seats=[0,1,2,3],pairs=[];for(let i=0;i<3;i++){pairs.push([seats[0],seats[2]].sort().join(''),[seats[1],seats[3]].sort().join(''));seats=rotateSeats(seats);}assert.equal(new Set(pairs).size,6);assert.deepEqual(seats,[0,1,2,3]);});
test('balance individual pendiente: ninguna liquidacion sin tres series y cuatro conformidades',()=>{const balances=[19600,19600,19600,19600],series=[{number:1,difference:600,movements:[600,-600,600,-600],seats:[0,1,2,3]},{number:2,difference:200,movements:[200,-200,200,-200],seats:[1,3,2,0]},{number:3,difference:-100,movements:[-100,100,-100,100],seats:[3,0,2,1]}];assert.deepEqual(individualTotals(series),[500,-300,700,-900]);assert.throws(()=>finalBalances(balances,series.slice(0,2),[true,true,true,true]));assert.throws(()=>finalBalances(balances,series,[true,true,false,true]));assert.deepEqual(balances,[19600,19600,19600,19600]);const next=finalBalances(balances,series,[true,true,true,true]);assert.deepEqual(next,[20100,19300,20300,18700]);assert.equal(next.reduce((a,b)=>a+b,1600),80000);});

test('vulnerabilidad fija por mano y premios de manga 300/500',()=>{assert.deepEqual([0,1,2,3].map(seriesVulnerability),['None','EW','NS','Both']);for(let index=0;index<4;index++)for(const seat of [0,1]){const r=seriesHand({...emptyRubber(),hands:index},hand(3,'NT',9,seat));const expected=seriesVulnerability(index)==='Both'||seriesVulnerability(index)===(seat%2===0?'NS':'EW')?500:300;assert.equal(r.above[seat],expected);assert.equal(r.below[seat],100);}});
test('valor de contrato: 20 menores, 30 mayores, 40 primera SA mas 30 siguientes',()=>{for(const [strain,level,tricks,points] of [['C',1,7,20],['D',2,8,40],['H',1,7,30],['S',2,8,60],['NT',1,7,40],['NT',2,8,70]]){const r=seriesHand(emptyRubber(),hand(level,strain,tricks));assert.equal(r.below[0],points);assert.equal(r.above[0],0);}});

test('ejemplo Alejandro: 4 picas justas 420 no vulnerable y 620 vulnerable',()=>{const nv=seriesHand(emptyRubber(),hand(4,'S',10));assert.equal(nv.below[0],120);assert.equal(nv.above[0],300);assert.equal(nv.above[0]+nv.below[0],420);const vul=seriesHand({...emptyRubber(),hands:2},hand(4,'S',10));assert.equal(vul.below[0],120);assert.equal(vul.above[0],500);assert.equal(vul.above[0]+vul.below[0],620);});

