export type PendingSeries={number:number;difference:number;movements:number[];seats:number[]};
export function individualTotals(series:PendingSeries[]){return [0,1,2,3].map(id=>series.reduce((n,s)=>n+s.movements[s.seats.indexOf(id)],0));}
export function rotateSeats(seats:number[]){const [n,e,s,w]=seats;return [e,w,s,n];}
export function finalBalances(balances:number[],series:PendingSeries[],approvals:boolean[]){if(series.length!==3)throw Error('Faltan series para completar todos contra todos.');if(approvals.length!==4||!approvals.every(Boolean))throw Error('Faltan conformidades.');const totals=individualTotals(series);if(totals.reduce((a,b)=>a+b,0)!==0)throw Error('El balance no cuadra.');const next=balances.map((n,i)=>n+totals[i]);if(next.some(n=>n<0))throw Error('Saldo insuficiente: liquidación pendiente, sin movimientos.');return next;}
